@@ -4163,7 +4169,30 @@ procedure TAes.Decrypt(const BI: TAesBlock; var BO: TAesBlock);
 
 procedure TAes.DoBlocks(pIn, pOut: PAesBlock; out oIn, oOut: PAesBLock;
   Count: integer; doEncrypt: boolean);
+{$ifdef ASMAESNI}
+var
+  p: TAesNiBlocks4Params;
+  n: integer;
+{$endif ASMAESNI}
 begin
+  {$ifdef ASMAESNI}
+  if (Count >= 4) and
+     (aesNi in Flags) then
+  begin
+    n := Count and not 3; // number of complete 4-block groups
+    p.ctxt := @self;
+    p.src := pIn;
+    p.dst := pOut;
+    p.groups := n shr 2;
+    if doEncrypt then
+      AesNiEncryptBlocks4(p)
+    else
+      AesNiDecryptBlocks4(p);
+    inc(pIn, n);
+    inc(pOut, n);
+    dec(Count, n); // 0..3 blocks left for the ordinary per-block path
+  end;
+  {$endif ASMAESNI}
   if Count > 0 then
     repeat
       DoBlock(self, pIn^, pOut^);

